import{_ as t,c as s,o as a,ag as n}from"./chunks/framework.CoPVQkzc.js";const m=JSON.parse('{"title":"Architecture Overview","description":"How OIE is structured internally","frontmatter":{"title":"Architecture Overview","description":"How OIE is structured internally"},"headers":[],"relativePath":"engine/architecture_overview.md","filePath":"engine/architecture_overview.md","lastUpdated":1788476353000}'),o={name:"engine/architecture_overview.md"};function r(i,e,c,l,d,h){return a(),s("div",null,e[0]||(e[0]=[n(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>The Open Integration Engine (OIE) is an open source standards-based healthcare integration engine that enables interoperability between two systems by accepting incoming information packets, called messages, and processing them according to rules you provide. It speeds message routing, filtering, and transformation between health-info systems using various message formats (e.g., HL7, X12, EDI, DICOM, XML).</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><p>Channels are the fundamental building blocks of OIE. A channel is an interface you configure to receive data from a source, take actions on that data (filter, transform, extract), and send it out to one or more destinations.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐    ┌─────────────────────────────────────────┐    ┌─────────────────┐</span></span>
<span class="line"><span>│  Source   │───&gt;│            OIE Channel                  │───&gt;│  Destination     │</span></span>
<span class="line"><span>│  System   │    │  Source Connector → Filter/Transformer  │    │  System(s)       │</span></span>
<span class="line"><span>└──────────┘    │               → Destination Connector(s) │    └─────────────────┘</span></span>
<span class="line"><span>                └─────────────────────────────────────────┘</span></span></code></pre></div><p>Each channel has general properties including a unique ID, name, and description. Channels can also be configured with code template library links, library resources, deploy/start dependencies (to control deployment order), attachment handler settings, message storage and pruning settings, and custom metadata columns.</p><h3 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h3><p>A channel consists of multiple <strong>connectors</strong>:</p><ul><li><strong>Source Connector</strong>. Gets data into OIE from an external system. Every channel has exactly one source connector. Source connectors may also include a <strong>source queue</strong> (when ON, messages are queued and a response is sent immediately before processing completes), a <strong>batch processor</strong> (to split incoming data into multiple messages), a <strong>response selector</strong> (to choose which response to return), and a <strong>max processing threads</strong> setting (to control concurrent processing).</li><li><strong>Destination Connectors</strong>. Sends data out to external systems. A channel has at least one, and may have multiple destination connectors. Each destination has an <strong>enabled</strong> flag and a <strong>wait for previous destination</strong> setting that determines its chain membership. Destinations also include a <strong>response transformer</strong> for processing responses received from external systems.</li></ul><p>For example, you may receive data over HTTP, then write it out to a file <strong>and</strong> insert pieces of it into a database.</p><p>See <a href="./channels_and_connectors.html">Channels and Connectors</a> and <a href="./connector_reference.html">Connector Reference</a> for details.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>A filter decides whether a message should proceed to the next step or not. A filter returns <strong>true</strong> (accepted) or <strong>false</strong> (filtered). Filters are comprised of multiple <strong>rules</strong>, joined by <strong>AND</strong> or <strong>OR</strong> operators.</p><ul><li>If the source connector filters out a message, it will not be processed by any destination connectors.</li><li>If a destination connector filters out a message, other destinations may still process it.</li></ul><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="transformers" tabindex="-1">Transformers <a class="header-anchor" href="#transformers" aria-label="Permalink to &quot;Transformers&quot;">​</a></h3><p>A transformer modifies a message, converts it from one format to another, and extracts pieces for later use. A transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong> (e.g., HL7 v2.x to JSON). Transformers are comprised of multiple <strong>steps</strong>, each of which modifies or extracts data.</p><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h3><p>A data type tells a filter/transformer how to parse a certain format. The <strong>inbound</strong> data type <strong>serializes</strong> raw data into an internal representation that filters and transformers can work with. The <strong>outbound</strong> data type <strong>deserializes</strong> transformed data back into the actual outbound format.</p><p>The internal representation varies by data type. For example, HL7 v2.x data is serialized into an E4X XML object, JSON data becomes a JavaScript Object, and Raw data remains a Java String with no serialization.</p><p>Supported data types include:</p><ul><li>Delimited Text</li><li>DICOM</li><li>EDI / X12</li><li>HL7 v2.x</li><li>HL7 v3.x</li><li>JSON</li><li>NCPDP</li><li>Raw</li><li>XML</li></ul><p>See <a href="./data_types_and_formats.html">Data Types and Formats</a> for details.</p><h2 id="message-processing-lifecycle" tabindex="-1">Message processing lifecycle <a class="header-anchor" href="#message-processing-lifecycle" aria-label="Permalink to &quot;Message processing lifecycle&quot;">​</a></h2><p>The raw inbound message enters OIE, is received by the source connector, filtered, <strong>transformed, then encoded</strong> and sent to the destination connector(s). Each destination can apply its own filters and transformers.</p><h3 id="source-processing-steps" tabindex="-1">Source processing steps <a class="header-anchor" href="#source-processing-steps" aria-label="Permalink to &quot;Source processing steps&quot;">​</a></h3><ol><li>A message or stream of data is received by the source connector</li><li>The batch processor decides whether to split the data into multiple messages. If so, the remaining steps are repeated for each message returned by the batch processor.</li><li>The attachment handler extracts and/or stores attachment data</li><li>The post-attachment-handler content is stored as <em>raw</em> data</li><li>Content runs through the preprocessor script and is stored as <em>processed raw</em> data</li><li>Content is serialized to the internal representation of the <strong>inbound data type</strong> (e.g., XML)</li><li>Content runs through the filter and is either accepted or filtered. If filtered, flow jumps directly to the Final Processing Steps.</li><li>Content runs through the transformer, where it may be modified</li><li>Post-transformer content is stored as <em>transformed</em> data</li><li>Content is deserialized from the <strong>outbound data type</strong> into the actual outbound format</li><li>Content is stored as <em>encoded</em> data</li><li>The resulting content is passed to the first destination connector of each destination chain</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If no filter or transformer is configured, there will not be any transformed or encoded data. In that case, the content used from here on will be the raw data (or processed raw data if a preprocessor modified it).</p></div><h3 id="destination-processing-steps" tabindex="-1">Destination processing steps <a class="header-anchor" href="#destination-processing-steps" aria-label="Permalink to &quot;Destination processing steps&quot;">​</a></h3><p>These steps are repeated for each destination connector that a message flows through:</p><ol><li>The encoded content from the source connector is used as <em>raw</em> data</li><li>Content is serialized to the internal representation of the <strong>inbound data type</strong></li><li>Content runs through the filter and is either accepted or filtered. If filtered, flow stops for this destination. If there are more destinations in the current chain, these steps repeat for the next one. Otherwise, flow proceeds to the Final Processing Steps.</li><li>Content runs through the transformer, where it may be modified</li><li>Post-transformer content is stored as <em>transformed</em> data</li><li>Content is deserialized from the <strong>outbound data type</strong> into the actual outbound format</li><li>Content is stored as <em>encoded</em> data</li><li>The destination connector builds a message from all available previous content, stores it as <em>sent</em> data, and sends it to the outbound system</li><li>A response is received and stored as <em>response</em> data</li><li>If a response transformer is configured, the response is serialized to the internal representation of the <strong>response inbound data type</strong></li><li>The response runs through the response transformer, where it may be modified</li><li>Post-response-transformer content is stored as <em>response transformed</em> data</li><li>The response is deserialized from the <strong>response outbound data type</strong> into the actual outbound format</li><li>The response is stored as <em>processed response</em> data</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If no filter or transformer is configured, there will not be any transformed or encoded data. In that case, the content used from here on will be the raw data only.</p></div><h3 id="final-processing-steps" tabindex="-1">Final processing steps <a class="header-anchor" href="#final-processing-steps" aria-label="Permalink to &quot;Final processing steps&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This point is reached when all destination chains have finished processing the message. If the message was filtered or errored out on the source connector, flow jumps directly to this step.</p></div><ol><li>The post processor script is executed. It can return a response that the source connector may use.</li><li>The source connector decides what response to send back to the originating system, if any. This may be an auto-generated value, the response payload from a destination connector, a response returned from the post processor script, or a custom value from the response map.</li><li>The selected response is stored and sent back to the originating system.</li></ol><h3 id="destination-chains" tabindex="-1">Destination chains <a class="header-anchor" href="#destination-chains" aria-label="Permalink to &quot;Destination chains&quot;">​</a></h3><p>A channel&#39;s destinations are grouped into one or more <strong>destination chains</strong>. Each chain processes simultaneously with respect to other chains, but within a chain, messages flow through each destination <strong>in order</strong>. This allows parallel processing across chains while maintaining order within a chain.</p><h2 id="message-data" tabindex="-1">Message data <a class="header-anchor" href="#message-data" aria-label="Permalink to &quot;Message data&quot;">​</a></h2><h3 id="messages-and-connector-messages" tabindex="-1">Messages and connector messages <a class="header-anchor" href="#messages-and-connector-messages" aria-label="Permalink to &quot;Messages and connector messages&quot;">​</a></h3><p>A <strong>message</strong> refers to a single overall dispatch of data through the source connector and destination connectors within a channel. Messages are further divided into <strong>connector messages</strong>, the portions of the message that flow through a single connector. For example, a channel with two destinations will have three connector messages per message: one for the source connector and one for each destination.</p><p>Messages do not always correspond 1-to-1 with incoming data. If a source connector has a batch processor enabled, a single incoming file containing 100 HL7 v2.x messages could be split and processed as 100 separate messages.</p><h3 id="message-metadata" tabindex="-1">Message metadata <a class="header-anchor" href="#message-metadata" aria-label="Permalink to &quot;Message metadata&quot;">​</a></h3><p>Each message carries metadata used for tracking and diagnostics:</p><ul><li><strong>Message ID</strong>. A unique integer ID per channel, used to group connector messages together in the message browser.</li><li><strong>Connector Metadata ID</strong>. Each connector has its own ID. The source connector is always 0. Destination connectors start at 1 and increment for each destination added.</li><li><strong>Status</strong>. The current processing state of each connector message (e.g., RECEIVED, QUEUED, SENT, ERROR).</li><li><strong>Timestamps</strong>. Every connector message stores a <strong>received date</strong>. Destination connectors also store <strong>send date</strong> and <strong>response date</strong>. Comparing these timestamps helps diagnose performance issues.</li><li><strong>Custom Metadata Columns</strong>. User-defined columns that extract data from messages for display and searching in the message browser.</li></ul><h3 id="message-content-types" tabindex="-1">Message content types <a class="header-anchor" href="#message-content-types" aria-label="Permalink to &quot;Message content types&quot;">​</a></h3><p>As a message flows through a channel, different versions of the data are stored for each connector:</p><p><strong>Source connector:</strong> Raw, Processed Raw, Transformed, Encoded, Response</p><p><strong>Destination connector:</strong> Raw, Transformed, Encoded, Sent, Response, Response Transformed, Processed Response</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When a message flows from the source to destination connectors, the source&#39;s Encoded Data becomes the Raw Data for each destination. Raw Data is <strong>not</strong> daisy-chained from destination to destination. Every destination receives the same source Encoded Data as its starting point.</p></div><h3 id="message-attachments" tabindex="-1">Message attachments <a class="header-anchor" href="#message-attachments" aria-label="Permalink to &quot;Message attachments&quot;">​</a></h3><p>An attachment is a piece of data extracted from the raw incoming message and stored separately. Extraction happens at the very beginning of the message lifecycle, before the preprocessor script runs. Because multiple copies of the message data are stored as it flows through a channel (raw, transformed, encoded), storing large pieces as attachments reduces memory usage. Attachments are automatically re-inserted into outgoing data when a destination connector dispatches.</p><p>See <a href="./message_processing.html">Message Processing</a> for details.</p><h2 id="channel-scripts" tabindex="-1">Channel scripts <a class="header-anchor" href="#channel-scripts" aria-label="Permalink to &quot;Channel scripts&quot;">​</a></h2><p>Four special scripts are associated with each channel:</p><ul><li><strong>Deploy Script</strong>. Runs once right before a channel is deployed.</li><li><strong>Preprocessor Script</strong>. Runs once for every message, after the attachment handler has optionally extracted data, but before the source filter/transformer. Used to modify the incoming message.</li><li><strong>Post Processor Script</strong>. Runs once for every message, after the source connector and all destinations have completed (excluding asynchronous processes like the destination queue), but before a response is sent back to the originating system. Has access to responses from all executed destinations and can return a custom response for the source connector to use.</li><li><strong>Undeploy Script</strong>. Runs once right before a channel is undeployed.</li></ul><h2 id="administration-interfaces" tabindex="-1">Administration interfaces <a class="header-anchor" href="#administration-interfaces" aria-label="Permalink to &quot;Administration interfaces&quot;">​</a></h2><ul><li><strong>Administrator</strong>. A Java Swing desktop client for managing channels, viewing messages, configuring settings, and monitoring the system. Connects to the server over HTTPS using a RESTful API. Requires a compatible launcher; see <a href="./desktop_administrator.html">Desktop Administrator</a> for the available options.</li><li><strong><a href="./web_administrator.html">Web Administrator</a></strong>. A browser-based administrator installed as the Web Support extension and served by the engine&#39;s own embedded Jetty. Read/write against the same REST API, so it and the desktop client can be used against one engine at the same time. Requires 4.6.0.</li><li><strong>Command Line Interface (CLI)</strong>. A terminal-based client for scripting and headless administration. Uses the same REST API as the Administrator.</li></ul><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><p>OIE uses a plugin architecture where connectors, data types, and other features are loaded as extensions. Extension types include:</p><ul><li><strong>Connectors</strong>. Source and destination communication protocols</li><li><strong>Data Type Plugins</strong>. Message format parsers and serializers</li><li><strong>Server Plugins</strong>. Background services and event handlers</li><li><strong>Transmission Mode Providers</strong>. Frame-level protocol handling (e.g., MLLP)</li></ul><p>Extensions are discovered at runtime, so one install serves both the desktop and web administrators. A growing set of open source extensions is available beyond those bundled with the engine. See <a href="./extension_catalog.html">Plugins and Extensions</a>.</p>`,63)]))}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
